const courseLessons = [
  {title:"Present perfect vs past simple",level:"B1",focus:"Use the past simple for finished time; use the present perfect for experience or a past action connected to now.",examples:["I visited London last year.","I have visited London three times."],questions:[
    {q:"I _____ this film yesterday.",choices:["have seen","saw","see"],answer:1,why:"Yesterday is a finished time, so use the past simple."},
    {q:"She _____ already finished her project.",choices:["has","did","was"],answer:0,why:"Use the present perfect for a completed action connected to now."},
    {q:"Which phrase usually refers to a finished past time?",choices:["so far","last Monday","recently"],answer:1,why:"Last Monday identifies a finished time in the past."}
  ]},
  {title:"Articles: a, an, the and no article",level:"B1",focus:"Use a/an for a non-specific singular countable noun, the for something specific or known, and no article for general plural or uncountable nouns.",examples:["I saw a dog. The dog was wearing a red collar.","Creativity takes time."],questions:[
    {q:"I bought _____ interesting book.",choices:["a","an","the"],answer:1,why:"Interesting begins with a vowel sound, so use an."},
    {q:"_____ water in this bottle is cold.",choices:["A","The","No article"],answer:1,why:"The bottle identifies specific water."},
    {q:"_____ students need feedback.",choices:["A","The","No article"],answer:2,why:"No article is used for students in general."}
  ]},
  {title:"Gerunds and infinitives",level:"B1–B2",focus:"Some verbs are followed by -ing, others by to + verb. Learn the pattern with the verb rather than translating word by word.",examples:["She enjoys drawing.","They decided to leave."],questions:[
    {q:"He suggested _____ a break.",choices:["to take","taking","take"],answer:1,why:"Suggest is followed by a gerund."},
    {q:"We hope _____ the results soon.",choices:["to receive","receiving","receive"],answer:0,why:"Hope is commonly followed by to + infinitive."},
    {q:"I avoid _____ late at night.",choices:["to drive","drive","driving"],answer:2,why:"Avoid is followed by a gerund."}
  ]},
  {title:"Conditionals: real and unreal situations",level:"B1–B2",focus:"Use zero/first conditional for facts and possible futures; use second conditional for imagined situations; use third conditional for unreal past events.",examples:["If it rains, we will stay inside.","If I had more time, I would learn Japanese.","If she had called, I would have helped."],questions:[
    {q:"If I _____ more time, I would travel more.",choices:["have","had","will have"],answer:1,why:"Second conditional uses if + past simple."},
    {q:"If you heat ice, it _____.",choices:["melts","will melted","would melt"],answer:0,why:"Zero conditional describes a general fact."},
    {q:"If they had left earlier, they _____ the train.",choices:["would catch","would have caught","caught"],answer:1,why:"Third conditional uses would have + past participle."}
  ]},
  {title:"Passive voice",level:"B1–B2",focus:"Use the passive when the action or result matters more than the person doing it. Form it with be + past participle.",examples:["The designer created the logo.","The logo was created by the designer."],questions:[
    {q:"The new bridge _____ next year.",choices:["will complete","will be completed","will have completing"],answer:1,why:"Future passive: will be + past participle."},
    {q:"The room _____ at the moment.",choices:["is being cleaned","is cleaning","has cleaned"],answer:0,why:"Present continuous passive: is being + past participle."},
    {q:"Which sentence is passive?",choices:["They built the house.","The house was built in 1990.","They are building a house."],answer:1,why:"The subject receives the action: was built."}
  ]},
  {title:"Linking ideas clearly",level:"B2",focus:"Use linking expressions to show contrast, reason, result and concession. Choose the connector that matches the relationship between ideas.",examples:["Although it was raining, we went out.","The plan was expensive; therefore, we changed it.","Despite the delay, the team finished."],questions:[
    {q:"_____ the weather was bad, the event continued.",choices:["Although","Despite","Therefore"],answer:0,why:"Although is followed by a subject and verb."},
    {q:"The train was delayed. _____, we arrived late.",choices:["However","As a result","Although"],answer:1,why:"As a result introduces a consequence."},
    {q:"_____ being tired, she kept working.",choices:["Although","Despite","Because"],answer:1,why:"Despite is followed by a noun or gerund."}
  ]}
];

